-- migration_015_new_questions_sept2026d.sql
-- Batch 4 of new questions from "Questions to add.pdf": whiplash-associated
-- disorder outcomes (Clinical Pain), hazards of ionising radiation
-- (Physics & Clinical Measurement), and the STarT Back Screening Tool
-- (Psychology).
--
-- The whiplash question carries a knowledge box with the Quebec WAD
-- classification, diagnosis and chronic-WAD treatment tables. The STarT Back
-- question embeds two new SVG figures (images/start-back-screening-tool.svg,
-- images/start-back-management-pathway.svg) and an orange NICE NG59 button.
--
-- Safe to run directly in the Supabase SQL Editor. Idempotent (on conflict do
-- nothing) so it can be re-run harmlessly. No new categories are introduced.

insert into questions (id, type, data, status) values ('q_mtf_whiplash_outcomes_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":91,"stem":"Which factors are associated with worse outcomes after a whiplash injury?","choices":["Age <40 years","Head-on collision","Severe pain immediately post-impact","Development of anxiety after the injury","Higher speed of impact"],"correct":[false,false,true,true,false],"explanation":"<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; Older age is associated with a worse prognosis in whiplash injury; increasing age is a recognised risk factor for prolonged symptoms and poorer recovery. Being under 40 is therefore not a poor-prognosis feature.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; WAD is usually caused by rear-end, low-impact collisions (around 90% of cases at speeds below 14 mph): the trunk is forced back against the seat with hyperextension of the neck, followed by forward recoil. A head-on mechanism is neither the typical cause nor a recognised predictor of worse outcome.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Severe initial pain intensity immediately after the injury is one of the most consistent and robust predictors of chronicity and poor long-term outcome in WAD.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Development of psychological distress after the injury &mdash; anxiety, depression, post-traumatic stress symptoms, fear-avoidance beliefs &mdash; is a well-recognised predictor of poor outcome and chronic WAD.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> &mdash; Whiplash is more common after low-speed collisions; a higher speed of impact is not an established predictor of worse WAD outcome.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Whiplash-Associated Disorders (WAD)</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Whiplash is an acceleration&ndash;deceleration mechanism of energy transfer to the neck. It usually results from rear-end or side-impact motor vehicle collisions but can also occur with diving and other mishaps.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The impact may cause bony or soft-tissue injury (the whiplash injury), which in turn produces the range of clinical manifestations termed whiplash-associated disorders (WAD).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology &amp; burden</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Incidence is high &mdash; around 9 per 1000 in the UK, the highest in Europe</td></tr><tr><td>Whiplash injuries cost the UK economy approximately &pound;3.64 billion per year and account for around 76% of motor-insurance claims</td></tr><tr><td>In about 60% of patients the pain arises from the zygapophysial (facet) joints &mdash; especially C2/3 and C5/6 &mdash; rather than from muscle</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Risk factors for sustaining a whiplash injury</div><table style=\"margin:0\"><tr><th>Risk factor</th></tr><tr><td>Female sex (thinner necks)</td></tr><tr><td>Short neck; a car seat with a low head restraint</td></tr><tr><td>Rear-end collision with a heavy vehicle</td></tr><tr><td>A car seat with an elastic back reduces the risk of neck injury in a crash</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Quebec classification of WAD</div><table style=\"margin:0\"><tr><th>Grade</th><th>Clinical features</th><th>Radiography</th><th>Pharmacotherapy</th></tr><tr><td>0</td><td>No neck pain, stiffness or physical signs (asymptomatic)</td><td>Not required</td><td>Not required</td></tr><tr><td>I</td><td>Neck pain, stiffness or tenderness only; no physical signs</td><td>Not required</td><td>Simple analgesics</td></tr><tr><td>II</td><td>Neck pain plus musculoskeletal signs (reduced range of movement, point tenderness)</td><td>Plain cervical X-ray usually not required unless suspected bony injury, impaired consciousness masking pain, or a high-speed / high-impact collision</td><td>Non-opioid analgesics; NSAIDs</td></tr><tr><td>III</td><td>Neck pain plus neurological signs (sensory deficit, motor weakness, reduced or absent reflexes)</td><td>Baseline cervical X-ray (AP, lateral, open-mouth views); specialised imaging may be needed</td><td>Non-opioid analgesics; NSAIDs; opioids for a limited period in acute severe cases</td></tr><tr><td>IV</td><td>Neck pain plus dislocation or fracture, with or without spinal cord injury</td><td>Specialised imaging (CT, MRI, myelography, discography)</td><td>Non-opioid analgesics; NSAIDs; opioids; immediate referral to a specialist surgeon</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic whiplash</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Around 40% of patients have WAD symptoms beyond 3 months (chronic whiplash)</td></tr><tr><td>2&ndash;4.5% are left permanently disabled</td></tr><tr><td>Patients who are asymptomatic at 3 months generally remain so at 2 years</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Markers of delayed recovery / worse outcome</div><table style=\"margin:0\"><tr><th>Marker</th></tr><tr><td>Severe, rapid-onset neck pain and stiffness after the injury</td></tr><tr><td>Neurological deficit or arm pain; headache</td></tr><tr><td>Acute hospital admission</td></tr><tr><td>Older age at the time of injury</td></tr><tr><td>Pre-existing neck pain or low back pain</td></tr><tr><td>Female sex, part-time employment, lower educational attainment, lawyer involvement</td></tr><tr><td>Depression, anxiety and mood disorders (common in chronic whiplash)</td></tr></table><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">When one or more of these adverse indicators is present, patients usually need more intensive treatment and earlier referral to physiotherapy, a pain physician, or a specialist with an interest in WAD.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnosis</div><table style=\"margin:0\"><tr><th>Step</th><th>Detail</th></tr><tr><td>History</td><td>Sudden or excessive neck extension, flexion or rotation. Symptoms may be delayed hours to days. The two most common complaints are headache and disabling neck pain, with or without referral to the shoulder or arm.</td></tr><tr><td>Examination</td><td>Look for muscle spasm, point tenderness, and upper- or lower-limb neurological signs; assess neck range of movement. Screen for red flags (myelopathy / cord compression, cancer, severe trauma or skeletal injury, vascular insufficiency).</td></tr><tr><td>Psychosocial assessment</td><td>Identify yellow flags (stress, anxiety, depression). WAD is more likely to become chronic in people with anxiety, depression, hypochondriasis, obsessive-compulsive traits, or high somatisation scores.</td></tr><tr><td>Imaging</td><td>Acute-phase imaging generates many false positives &mdash; reserve it for red-flag features or persistent arm pain. The commonest finding is pre-existing degenerative change (especially C5/6 spondylosis), sometimes with loss of the normal cervical lordosis; dynamic flexion&ndash;extension films may show a kyphotic angle from protective muscle spasm.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Treatment of chronic WAD</div><table style=\"margin:0\"><tr><th>Approach</th><th>Detail</th></tr><tr><td>Multimodal rehabilitation</td><td>Cognitive behavioural therapy combined with physical / mechanical therapy and patient education</td></tr><tr><td>Cervical medial branch radiofrequency neurotomy</td><td>Facet-joint denervation gives reasonable pain relief for up to ~9 months in around 70% of patients</td></tr><tr><td>Interventions with weak or absent evidence</td><td>Cervical facet joint injections, temporomandibular joint treatment, cervical traction, botulinum toxin injections</td></tr><tr><td>Pharmacological</td><td>Simple analgesics, with antineuropathic agents added for symptom control</td></tr><tr><td>Neurological deficit</td><td>More aggressive management, including surgical treatment</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ionising_radiation_hazards_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":92,"stem":"The following are hazards of ionising radiation:","choices":["Cataract formation","Graves'' disease","Eczema","Increased risk of malignancy","Skin erythema / burns"],"correct":[true,false,false,true,true],"explanation":"<p>Ionising radiation exposure &mdash; relevant to fluoroscopy in interventional pain procedures &mdash; produces two categories of harm: stochastic effects (probability-based, no safe threshold, e.g. malignancy) and deterministic effects (threshold-dependent, with severity rising as dose increases, e.g. cataract, skin burns).</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; The lens of the eye is particularly radiosensitive, and cataract is a well-recognised deterministic effect of cumulative exposure &mdash; a key reason lead glasses / eye protection are advised for staff who perform frequent fluoroscopic procedures.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; Graves'' disease is an autoimmune cause of hyperthyroidism and is not a recognised consequence of ionising radiation. Thyroid irradiation is instead linked to thyroid malignancy (hence thyroid shielding during fluoroscopy), not autoimmune thyroid disease.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> &mdash; Eczema is an inflammatory dermatosis with no established causal link to ionising radiation. Radiation skin effects are distinct &mdash; erythema, burns, and later atrophy / fibrosis (radiation dermatitis).</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Increased malignancy risk is the classic stochastic effect of ionising radiation: there is no established safe threshold and risk accumulates with lifetime dose, underpinning the ALARA (\"as low as reasonably achievable\") principle in radiation protection.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Skin erythema and burns are recognised deterministic effects of ionising radiation exposure.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_start_back_tool_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":93,"stem":"Regarding the STarT Back Screening Tool:","choices":["It is validated for use in a chronic pain clinic setting to stratify ongoing management of chronic pain patients","It consists of 9 items, including 5 that assess psychosocial factors","Patients classified as medium risk are best managed with a combined physical and psychological treatment approach targeting the psychosocial subscore","A score of 3 or more is classified as medium risk","The tool''s items include assessment of referred leg pain, comorbid pain elsewhere in the body, and disability with activities such as walking and dressing"],"correct":[false,true,false,false,true],"explanation":"<p>The STarT Back Screening Tool (SBST) is a brief prognostic questionnaire developed and validated in primary care to stratify people with a new or recurrent episode of non-specific low back pain into low-, medium- or high-risk groups, guiding early matched treatment.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; The tool is validated in primary care low back pain populations to guide initial treatment stratification. It is not validated for ongoing management of established chronic pain in a pain-clinic setting &mdash; by that point patients have usually moved beyond this first-presentation decision.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; There are 9 items in total: 4 physical and 5 psychosocial (bothersomeness, catastrophising, fear, anxiety, and low mood).</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> &mdash; Medium-risk patients (high total score but low psychosocial subscore) receive standard physiotherapy targeting physical obstacles to recovery. The combined physical and psychological approach targeting psychosocial factors is the high-risk pathway.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> &mdash; A total score of 4 or more is required for medium (or high) risk; a total score of 3 or less is low risk.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Referred leg pain, pain elsewhere (neck or shoulder), and difficulty with walking and dressing are among the 4 physical subscale items (the fourth being interference with usual activities / work).</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">STarT Back Screening Tool</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The STarT Back Tool was developed and validated for primary care patients presenting with a new or recurrent episode of low back pain, to guide early stratified management.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">It is a prognostic risk-stratification instrument for the point of first presentation &mdash; not a tool for ongoing stratification of established chronic pain-clinic patients, who have generally already passed this initial primary-care decision point.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The 9 items</div><div style=\"text-align:center\"><img src=\"images/start-back-screening-tool.svg\" alt=\"STarT Back Screening Tool questionnaire: items 1-4 form the physical subscale (leg pain, neck or shoulder pain, walking only short distances, dressing slowly) and items 5-9 the psychosocial subscale (fear of activity, worrying thoughts, catastrophising, anhedonia, and overall bothersomeness); each agree response scores 1, total 0-9\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Scoring and stratified management</div><div style=\"text-align:center\"><img src=\"images/start-back-management-pathway.svg\" alt=\"STarT Back stratified management pathway: low risk (total score 3 or less) receives self-management and exercise advice; medium risk (total 4 or more, psychosocial subscale 3 or less) receives structured primary-care physiotherapy; high risk (total 4 or more, psychosocial subscale 4 or more) receives a combined physical and psychological programme\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Total score 0&ndash;9. A score of &le;3 is low risk. A score of &ge;4 is medium risk, unless the psychosocial subscale (items 5&ndash;9) is also &ge;4, which classifies the patient as high risk.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ng59'',''NICE NG59 &mdash; Low Back Pain &amp; Sciatica'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE NG59 &mdash; Low Back Pain &amp; Sciatica\n</button></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

-- link each new question to its (single) category
insert into question_categories (question_id, category_id)
  select 'q_mtf_whiplash_outcomes_001', id from categories where name = 'Clinical Pain'
  on conflict do nothing;
insert into question_categories (question_id, category_id)
  select 'q_mtf_ionising_radiation_hazards_001', id from categories where name = 'Physics & Clinical Measurement'
  on conflict do nothing;
insert into question_categories (question_id, category_id)
  select 'q_mtf_start_back_tool_001', id from categories where name = 'Psychology'
  on conflict do nothing;
